def cmp_semver(a, b):
    def parse_version(version):
        parts = version.split('-')
        main = parts[0].split('.')
        pre_release = parts[1] if len(parts) > 1 else None
        return [int(x) for x in main], pre_release

    def compare_identifiers(id1, id2):
        if id1.isdigit() and id2.isdigit():
            return int(id1) - int(id2)
        elif id1.isdigit():
            return -1
        elif id2.isdigit():
            return 1
        else:
            return (id1 > id2) - (id1 < id2)

    va, pra = parse_version(a)
    vb, prb = parse_version(b)

    for i in range(max(len(va), len(vb))):
        if i >= len(va):
            return -1
        if i >= len(vb):
            return 1
        diff = va[i] - vb[i]
        if diff != 0:
            return diff

    if pra is None and prb is not None:
        return 1
    if pra is not None and prb is None:
        return -1
    if pra is None and prb is None:
        return 0

    pra_parts = pra.split('.')
    prb_parts = prb.split('.')
    for i in range(max(len(pra_parts), len(prb_parts))):
        if i >= len(pra_parts):
            return -1
        if i >= len(prb_parts):
            return 1
        diff = compare_identifiers(pra_parts[i], prb_parts[i])
        if diff != 0:
            return diff

    return 0
