def parse_range(header, size):
    if not header.startswith('bytes='):
        return None

    ranges = []
    parts = header[6:].split(',')
    for part in parts:
        if '-' not in part:
            continue

        start, end = part.split('-')
        start = int(start) if start else 0
        end = int(end) if end else size - 1

        if start >= size:
            continue

        if end >= size:
            end = size - 1

        if start > end:
            continue

        ranges.append((start, end))

    if not ranges:
        return None

    return ranges
