def schedule(jobs):
    if not jobs:
        return 0

    jobs.sort(key=lambda x: x[1])
    n = len(jobs)
    dp = [0] * n
    dp[0] = jobs[0][2]

    for i in range(1, n):
        # Find the last job that finishes before the current job starts
        j = binary_search(jobs, i)
        if j != -1:
            dp[i] = max(dp[i-1], dp[j] + jobs[i][2])
        else:
            dp[i] = max(dp[i-1], jobs[i][2])

    return dp[-1]

def binary_search(jobs, i):
    start = 0
    end = i - 1
    while start <= end:
        mid = (start + end) // 2
        if jobs[mid][1] <= jobs[i][0]:
            if jobs[mid+1][1] > jobs[i][0]:
                return mid
            start = mid + 1
        else:
            end = mid - 1
    return -1
