class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []

    def find(self, x):
        return self.parent[x]

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.history.append((root_a, root_b, self.size[root_b]))
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            root_a, root_b, size_b = self.history.pop()
            self.parent[root_b] = root_b
            self.size[root_a] -= size_b

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)
