import heapq

def shortest_path(graph, src, dst):
    if src not in graph:
        return None, []

    # Priority queue for Dijkstra's algorithm
    pq = [(0, 0, [src])]  # (cost, edge_count, path)
    visited = set()

    while pq:
        cost, edge_count, path = heapq.heappop(pq)

        if path[-1] == dst:
            return cost, path

        if path[-1] in visited:
            continue

        visited.add(path[-1])

        for neighbor, weight in graph.get(path[-1], []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                heapq.heappush(pq, (cost + weight, edge_count + 1, new_path))

    return None, []

# Example usage:
# graph = {
#     'A': [('B', 1), ('C', 4)],
#     'B': [('C', 2), ('D', 5)],
#     'C': [('D', 1)],
#     'D': []
# }
