const pLimit = (n) => {
  let activeCount = 0;
  const queue = [];

  const run = async () => {
    if (activeCount < n && queue.length > 0) {
      activeCount++;
      const { resolve, reject, fn } = queue.shift();
      try {
        const result = await fn();
        resolve(result);
      } catch (error) {
        reject(error);
      } finally {
        activeCount--;
        run();
      }
    }
  };

  return (fn) => {
    return new Promise((resolve, reject) => {
      queue.push({ resolve, reject, fn });
      run();
    });
  };
};

