const setImmediatePromise = promisify(setImmediate);

async function toposortTasks(tasks) {
    const result = {};
    const visited = new Set();
    const visiting = new Set();
    const pending = new Map();

    async function runTask(name) {
        if (visiting.has(name)) {
            throw new Error(`cycle detected at ${name}`);
        }
        if (visited.has(name)) {
            return result[name];
        }
        visiting.add(name);
        try {
            const depsValues = await Promise.all(
                tasks[name].deps.map(depName => {
                    if (!tasks[depName]) {
                        throw new Error(`unknown dependency: ${depName}`);
                    }
                    return runTask(depName);
                })
            );
            const depsMap = tasks[name].deps.reduce((acc, depName, index) => {
                acc[depName] = depsValues[index];
                return acc;
            }, {});
            const taskResult = await tasks[name].run(depsMap);
            result[name] = taskResult;
        } finally {
            visiting.delete(name);
            visited.add(name);
        }
        return result[name];
    }

    const allTasks = Object.keys(tasks);
    await Promise.all(allTasks.map(taskName => runTask(taskName)));

    return result;
}

