export class Bus<E extends Record<string, unknown>> {
  private events: { [K in keyof E]?: ((payload: E[K]) => void)[] } = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.events[k]) {
      this.events[k] = [];
    }
    this.events[k]?.push(fn);
    return () => {
      this.events[k] = this.events[k]?.filter(f => f !== fn);
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K]): void {
    if (k in this.events) {
      this.events[k]?.forEach(fn => {
        if (k in payload) {
          fn(payload);
        } else {
          fn();
        }
      });
    }
  }
}
