type RequiredKeys<T> = {
  [K in keyof T]-?: T[K];
};

type OptionalKeys<T> = {
  [K in keyof T]?: T[K];
};

type BuilderState<T, K extends keyof T> = {
  config: Pick<T, K>;
  requiredKeys: K[];
};

export class Builder<T, K extends keyof T = never> {
  private state: BuilderState<T, K>;

  constructor(requiredKeys: K[]) {
    this.state = {
      config: {} as Pick<T, K>,
      requiredKeys,
    };
  }

  set<K2 extends keyof T>(key: K2, value: T[K2]): Builder<T, K | K2> {
    if (!(key in this.state.config)) {
      this.state.config[key] = value;
    }
    return new Builder<T, K | K2>(this.state.requiredKeys);
  }

  build(): RequiredKeys<Pick<T, K>> & OptionalKeys<Omit<T, K>> {
    const { config, requiredKeys } = this.state;
    const missingKeys = requiredKeys.filter(key => !(key in config));
    if (missingKeys.length > 0) {
      throw new Error(`Missing required keys: ${missingKeys.join(', ')}`);
    }
    return config as any;
  }
}

export function builder<T, K extends keyof T = never>(requiredKeys: K[]): Builder<T, K> {
  return new Builder<T, K>(requiredKeys);
}
