type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends object
  ? { [P in keyof T]: DeepAwaited<T[P]> }
  : T;

async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (typeof value === 'object' && value !== null) {
    if (Array.isArray(value)) {
      return Promise.all(value.map(deepAwait)) as any;
    } else {
      const result: any = {};
      for (const key in value) {
        result[key] = await deepAwait((value as any)[key]);
      }
      return result;
    }
  } else if (typeof value === 'function') {
    return value as any;
  } else if (value instanceof Promise) {
    return deepAwait(await value);
  } else {
    return value as any;
  }
}

export { DeepAwaited, deepAwait };
