// sol.ts

type RouteParams<Path extends string> = Path extends `${infer Start}:${infer Param}/${infer Rest}`
  ? { [K in Param]: string } & RouteParams<Rest>
  : Path extends `${infer Start}:${infer Param}`
  ? { [K in Param]: string }
  : {};

type RouteFunction<Path extends string> = RouteParams<Path> extends infer Params
  ? (params: Params) => string
  : () => string;

type RoutesObject<Routes extends Record<string, string>> = {
  [K in keyof Routes]: RouteFunction<Routes[K]>;
};

function defineRoutes<Routes extends Record<string, string>>(routes: Routes): RoutesObject<Routes> {
  return Object.fromEntries(
    Object.entries(routes).map(([name, path]) => [
      name,
      ((params?: any): string => {
        if (path.includes(':') && (!params || Object.keys(params).length === 0)) {
          throw new Error(`Route ${name} requires parameters`);
        }
        let result = path;
        for (const key in params) {
          const value = params[key];
          if (typeof value !== 'string') {
            throw new Error(`Parameter ${key} must be a string`);
          }
          result = result.replace(`:${key}`, value);
        }
        if (result.includes(':')) {
          throw new Error(`Missing parameter for route ${name}`);
        }
        return result;
      }) as RouteFunction<Routes[K]>,
    ])
  ) as RoutesObject<Routes>;
}

export { defineRoutes };
